                    layer={layer}
                    index={index}
                    isActive={index === activeLayer}
                    onEnter={() => setHoveredLayer(index)}
                    onLeave={() => setHoveredLayer(null)}
                  />
                </div>
              ))}
            </div>
          </div>
        </div>

        <ProgressIndicator activeLayer={activeLayer} onLayerClick={scrollToLayer} />
      </div>

      <div className="section-padding pt-8 md:pt-12">
        <div className="max-w-7xl mx-auto px-6 md:px-8 lg:px-12">
          <div className="bg-[#1E40AF] p-6 md:p-8 text-white border-[3px] border-[#1A1A2E] shadow-[6px_6px_0_#1A1A2E]">
            <div className="flex flex-col md:flex-row md:items-center gap-4 md:gap-8">
              <div className="flex-1">
                <p className="text-sm font-mono uppercase tracking-wide text-white/60 mb-2">
                  Key Insight
                </p>
                <p className="body-lg text-white">
                  OpenTelemetry is the second-highest velocity CNCF project, with Istio serving as the foundation for leading commercial offerings and widespread adoption for production AI workloads.
                </p>
              </div>
              <div className="text-4xl md:text-5xl font-bold text-white/30">#2</div>
            </div>
          </div>
        </div>
      </div>
    </section>
  );
}

/* Kubernetes Report 2026 Styles - Soft Brutalism Theme */

.kubernetes-report {
  /* Soft Brutalism + Royal Blue Theme */
  --k8s-background: #FAFAFA;
  --k8s-foreground: #1A1A2E;
  --k8s-card: #FFFFFF;
  --k8s-primary: #1E40AF;
  --k8s-primary-dark: #1E3A8A;
  --k8s-primary-light: #3B82F6;
  --k8s-secondary: #F3F4F6;
  --k8s-muted: #E5E7EB;
  --k8s-muted-foreground: #6B7280;
  --k8s-accent-emerald: #10B981;
  --k8s-accent-amber: #F59E0B;
  --k8s-accent-rose: #F43F5E;
  --k8s-accent-violet: #8B5CF6;
  --k8s-border: #1A1A2E;
  --k8s-section-light: #FAFAFA;
  --k8s-section-alt: #F3F4F6;
  --k8s-section-dark: #1A1A2E;
  --k8s-hero-gradient-start: #1E3A8A;
  --k8s-hero-gradient-end: #1E40AF;

  font-family: 'DM Sans', system-ui, sans-serif;
}

.kubernetes-report * {
  box-sizing: border-box;
}

/* Smooth scrolling */
.kubernetes-report {
  scroll-behavior: smooth;
}

/* Custom scrollbar */
.kubernetes-report::-webkit-scrollbar {
  width: 12px;
}

.kubernetes-report::-webkit-scrollbar-track {
  background: var(--k8s-secondary);
}

.kubernetes-report::-webkit-scrollbar-thumb {
  background: var(--k8s-primary);
  border: 2px solid var(--k8s-secondary);
}

.kubernetes-report::-webkit-scrollbar-thumb:hover {
  background: var(--k8s-primary-dark);
}

/* Brutalist Utilities */
.kubernetes-report .brutalist-border {
  border: 3px solid var(--k8s-border);
  box-shadow: 4px 4px 0 var(--k8s-border);
}

.kubernetes-report .brutalist-border-thin {
  border: 2px solid var(--k8s-border);
  box-shadow: 3px 3px 0 var(--k8s-border);
}

.kubernetes-report .brutalist-card {
  background: var(--k8s-card);
  border: 3px solid var(--k8s-border);
  box-shadow: 6px 6px 0 var(--k8s-border);
  transition: transform 0.2s ease, box-shadow 0.2s ease;
}

.kubernetes-report .brutalist-card:hover {
  transform: translate(-2px, -2px);
  box-shadow: 8px 8px 0 var(--k8s-border);
}

.kubernetes-report .brutalist-card-static {
  background: var(--k8s-card);
  border: 3px solid var(--k8s-border);
  box-shadow: 6px 6px 0 var(--k8s-border);
}

/* Hero Gradient */
.kubernetes-report .hero-gradient {
  background: linear-gradient(135deg, var(--k8s-hero-gradient-start) 0%, var(--k8s-hero-gradient-end) 100%);
}

/* Section Spacing */
.kubernetes-report .section-padding {
  padding-top: 80px;
  padding-bottom: 80px;
}

@media (max-width: 768px) {
  .kubernetes-report .section-padding {
    padding-top: 48px;
    padding-bottom: 48px;
  }
}

/* Typography */
.kubernetes-report .heading-xl {
  font-size: clamp(2.5rem, 5vw, 4rem);
  font-weight: 800;
  line-height: 1.1;
  letter-spacing: -0.02em;
}

.kubernetes-report .heading-lg {
  font-size: clamp(2rem, 4vw, 3rem);
  font-weight: 700;
  line-height: 1.2;
  letter-spacing: -0.01em;
}

.kubernetes-report .heading-md {
  font-size: clamp(1.5rem, 3vw, 2rem);
  font-weight: 700;
  line-height: 1.3;
}

.kubernetes-report .heading-sm {
  font-size: clamp(1.25rem, 2vw, 1.5rem);
  font-weight: 600;
  line-height: 1.4;
}

.kubernetes-report .body-lg {
  font-size: 1.125rem;
  line-height: 1.7;
}

.kubernetes-report .body-md {
  font-size: 1rem;
  line-height: 1.7;
}

/* Metric Display */
.kubernetes-report .metric-display {
  font-size: clamp(3rem, 8vw, 5rem);
  font-weight: 800;
  line-height: 1;
  letter-spacing: -0.03em;
}

/* Animation Classes */
.kubernetes-report .fade-in-up {
  opacity: 0;
  transform: translateY(20px);
  transition: opacity 0.6s ease, transform 0.6s ease;
}

.kubernetes-report .fade-in-up.visible {
  opacity: 1;
  transform: translateY(0);
}

/* Grid pattern */
.kubernetes-report .grid-pattern {
  background-image: 
    linear-gradient(var(--k8s-muted) 1px, transparent 1px),
    linear-gradient(90deg, var(--k8s-muted) 1px, transparent 1px);
  background-size: 40px 40px;
}

/* Focus states */
.kubernetes-report button:focus-visible,
.kubernetes-report a:focus-visible {
  outline: 3px solid var(--k8s-primary);
  outline-offset: 2px;
}

/* Border width utilities */
.kubernetes-report .border-3 {
  border-width: 3px;
}

